import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {validateMessage} from './validation.js';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';

// @ts-expect-error adding to the protocol
const UNSUPPORTED = 'UNSUPPORTED';

const wire = (sent: OutgoingMessage[]): string[] =>
  sent.map(frame => {
    if (frame.type === 'entry_upsert') {
      const content = 'content' in frame.entry ? frame.entry.content : '';
      return `upsert ${frame.index} ${frame.entry.role} ${JSON.stringify(content)}`;
    }
    if (frame.type === 'entry_delta') return `delta ${frame.index} ${JSON.stringify(frame.delta)}`;
    if (frame.type === 'entry_commit') return `commit ${frame.index}`;
    if (frame.type === 'entry_skip') return `skip ${frame.index}`;
    if (frame.type === 'error') return `error ${frame.code}`;
    if (frame.type === 'pong') return `pong ${frame.timestamp}`;
    if (frame.type === ('conversation_list' as any)) return `list ${(frame as any).conversations.length}`;
    if (frame.type === ('connected' as any)) return 'connected';
    if (frame.type === ('stream_end' as any)) return 'stream_end';
    return frame.type;
  });

const text = (value: string): MessageChunk => ({type: 'text', text: value});
const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
const afterPendingWork = () => new Promise(resolve => setImmediate(resolve));

interface StreamScript {
  pauseAfter?: {chunks: number; until: Promise<void>};
}

const harness = (chunks: MessageChunk[], {pauseAfter}: StreamScript = {}) => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;

  const stream = async function* (): AsyncGenerator<MessageChunk> {
    for (const [position, chunk] of chunks.entries()) {
      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
      yield chunk;
    }
  };

  const orchestrator = {processMessageStream: jest.fn(stream)} as unknown as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  return {
    ws,
    session,
    orchestrator,
    sent,
    frames: () => wire(sent),
  };
};

describe('conversation list acceptance', () => {
  describe('validation', () => {
    it('accepts a valid list_conversations frame', () => {
      // @ts-expect-error type 'list_conversations' is not yet known
      const result = validateMessage({type: 'list_conversations'});
      expect(result).toEqual({valid: true, data: {type: 'list_conversations'}});
    });

    it('accepts list_conversations with limit and before cursor', () => {
      const before = {updatedAt: '2026-01-01T00:00:00Z', sessionId: 's1'};
      // @ts-expect-error type 'list_conversations' is not yet known
      const result = validateMessage({type: 'list_conversations', limit: 10, before});
      expect(result).toEqual({valid: true, data: {type: 'list_conversations', limit: 10, before}});
    });

    it('rejects list_conversations with invalid limit', () => {
      // @ts-expect-error type 'list_conversations' is not yet known
      const result = validateMessage({type: 'list_conversations', limit: 0});
      expect(result.valid).toBe(false);
      expect(result.error).toContain('limit');
    });

    it('rejects list_conversations with invalid before cursor', () => {
      // @ts-expect-error BEFORE must have both updatedAt and sessionId as strings in the frame
      const result = validateMessage({type: 'list_conversations', before: {updatedAt: 'not-a-date', sessionId: 's1'}});
      expect(result.valid).toBe(false);
      expect(result.error).toContain('before');
    });
  });

  describe('handling', () => {
    it('returns conversation_list when history is enabled', async () => {
      const h = harness([]);
      const summaries = [{sessionId: 's1', createdAt: new Date('2026-01-01T00:00:00Z'), updatedAt: new Date('2026-01-01T00:00:00Z'), entryCount: 1}];
      const store = {listFor: jest.fn().mockResolvedValue(summaries)} as any;
      const config = {transport: {history: {enabled: true}}} as any;

      // @ts-expect-error createMessageHandler takes only 1 arg currently
      const handle = createMessageHandler(h.orchestrator, store, config);
      await handle(h.ws, h.session, {type: 'list_conversations'});

      expect(h.frames()).toEqual(['list 1']);
      expect(h.sent[0]).toMatchObject({
        type: 'conversation_list',
        conversations: [{
          sessionId: 's1',
          createdAt: '2026-01-01T00:00:00.000Z',
          updatedAt: '2026-01-01T00:00:00.000Z',
          entryCount: 1
        }]
      });
    });

    it('ignores userId in frame and uses ws.userId (from session)', async () => {
      const h = harness([]);
      const store = {listFor: jest.fn().mockResolvedValue([])} as any;
      const config = {transport: {history: {enabled: true}}} as any;

      // @ts-expect-error createMessageHandler takes only 1 arg currently
      const handle = createMessageHandler(h.orchestrator, store, config);
      await handle(h.ws, h.session, {type: 'list_conversations', userId: 'other-user'});

      expect(store.listFor).toHaveBeenCalledWith('u1', expect.anything());
    });

    it('returns UNSUPPORTED error when history is disabled', async () => {
      const h = harness([]);
      const store = {listFor: jest.fn()} as any;
      const config = {transport: {history: {enabled: false}}} as any;

      // @ts-expect-error createMessageHandler takes only 1 arg currently
      const handle = createMessageHandler(h.orchestrator, store, config);
      await handle(h.ws, h.session, {type: 'list_conversations'});

      expect(h.frames()).toEqual([`error ${UNSUPPORTED}`]);
    });

    it('returns UNSUPPORTED error when store does not implement listFor', async () => {
      const h = harness([]);
      const store = {} as any; // no listFor
      const config = {transport: {history: {enabled: true}}} as any;

      // @ts-expect-error createMessageHandler takes only 1 arg currently
      const handle = createMessageHandler(h.orchestrator, store, config);
      await handle(h.ws, h.session, {type: 'list_conversations'});

      expect(h.frames()).toEqual([`error ${UNSUPPORTED}`]);
    });

    it('returns SERVER_ERROR when listFor rejects', async () => {
      const h = harness([]);
      const store = {listFor: jest.fn().mockRejectedValue(new Error('db failed'))} as any;
      const config = {transport: {history: {enabled: true}}} as any;

      // @ts-expect-error createMessageHandler takes only 1 arg currently
      const handle = createMessageHandler(h.orchestrator, store, config);
      await handle(h.ws, h.session, {type: 'list_conversations'});

      expect(h.frames()).toEqual(['error SERVER_ERROR']);
      expect((h.sent[0] as any).message).not.toContain('db failed');
    });

    it('is answered off-lock', async () => {
      let releaseResolver: () => void = () => {};
      const until = new Promise<void>(res => { releaseResolver = res; });
      const h = harness([text('hi'), STOP], {pauseAfter: {chunks: 0, until}});
      const store = {listFor: jest.fn().mockResolvedValue([])} as any;
      const config = {transport: {history: {enabled: true}}} as any;

      // @ts-expect-error createMessageHandler takes only 1 arg currently
      const handle = createMessageHandler(h.orchestrator, store, config);

      const userMessage = handle(h.ws, h.session, {type: 'user_message', content: 'hello'});
      await afterPendingWork();

      const listRequest = handle(h.ws, h.session, {type: 'list_conversations'});
      await listRequest;

      expect(h.frames()).toContain('list 0');
      expect(h.frames()).not.toContain('stream_end');

      releaseResolver();
      await userMessage;
      expect(h.frames()).toContain('stream_end');
    });
  });
});

